function walk(dir, acc = []) {
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, e.name)
    if (e.isDirectory()) {
      walk(full, acc)
    } else if (e.name.endsWith('.html') && e.name !== '404.html') {
      acc.push(full)
    }
  }
  return acc
}
